<script setup lang="ts">
import {computed,onBeforeUnmount,ref} from 'vue';
import AppDialog from './AppDialog.vue';
const props=defineProps<{canEdit:boolean;request:<T>(path:string,method?:string,body?:unknown)=>Promise<T>}>();
const emit=defineEmits<{success:[message:string]}>();
type Configuration={id:number;sindicato_id:number;sindicato_nome?:string;nome:string;cnpj_filtro:string;categoria:string;uf:string;titulo:string;vigencia:string;tipos:string[];ativo:boolean};
type Union={id:number;nome:string};
const types=['Convenção Coletiva','Termo Aditivo de Convenção Coletiva','Acordo Coletivo','Termo Aditivo de Acordo Coletivo','Acordo Coletivo Específico - Programa de Proteção ao Emprego','Acordo Coletivo Específico - Autorização de Trabalho nos Domingos e Feriados','Termo Aditivo de Acordo Coletivo Programa de Proteção ao Emprego','Termo Aditivo de Acordo Coletivo - Autorização de Trabalho nos Domingos e Feriados','Todos os tipos'];
const states=['AC','AL','AP','AM','BA','CE','DF','ES','GO','MA','MT','MS','MG','PA','PB','PR','PE','PI','RJ','RN','RS','RO','RR','SC','SP','SE','TO'];
const defaults=()=>({sindicato_id:0,nome:'',cnpj_filtro:'',categoria:'',uf:'',titulo:'',vigencia:'',tipos:['Convenção Coletiva'],ativo:true});
const rows=ref<Configuration[]>([]),catalog=ref<Union[]>([]),loading=ref(true),failure=ref(''),query=ref(''),status=ref('todas'),editing=ref(false),editedId=ref<number|null>(null),deleting=ref<Configuration|null>(null),busy=ref(false),formError=ref(''),form=ref(defaults());let generation=0;
const visible=computed(()=>rows.value.filter(row=>(status.value==='todas'||String(row.ativo)===status.value)&&[row.nome,row.sindicato_nome,row.cnpj_filtro,row.categoria,row.uf,row.titulo,row.vigencia,...row.tipos].join(' ').toLocaleLowerCase('pt-BR').includes(query.value.toLocaleLowerCase('pt-BR'))));
async function load(){const current=++generation;loading.value=true;failure.value='';try{const [configurations,unions]=await Promise.all([props.request<Configuration[]>('/api/contexto/monitoramentos'),props.request<Union[]>('/api/contexto/sindicatos')]);if(current!==generation)return;rows.value=configurations;catalog.value=unions;}catch(error){if(current===generation)failure.value=(error as Error).message;}finally{if(current===generation)loading.value=false;}}
function edit(row?:Configuration){formError.value='';editedId.value=row?.id??null;form.value=row?{sindicato_id:row.sindicato_id,nome:row.nome,cnpj_filtro:row.cnpj_filtro,categoria:row.categoria,uf:row.uf,titulo:row.titulo,vigencia:row.vigencia,tipos:[...row.tipos],ativo:row.ativo}:defaults();editing.value=true;}
async function save(){if(busy.value||!props.canEdit)return;formError.value='';if(!form.value.tipos.length){formError.value='Selecione ao menos um tipo de instrumento.';return;}if(![form.value.cnpj_filtro,form.value.categoria,form.value.titulo].some(value=>value.trim())){formError.value='Informe CNPJ, categoria ou palavra no título para consultar.';return;}const current=generation;busy.value=true;try{await props.request('/api/contexto/monitoramentos'+(editedId.value?'/'+editedId.value:''),editedId.value?'PUT':'POST',form.value);if(current!==generation)return;editing.value=false;emit('success','Configuração salva.');await load();}catch(error){if(current===generation)formError.value=(error as Error).message;}finally{busy.value=false;}}
async function remove(){if(busy.value||!props.canEdit||!deleting.value)return;const current=generation;busy.value=true;formError.value='';try{await props.request('/api/contexto/monitoramentos/'+deleting.value.id,'DELETE');if(current!==generation)return;deleting.value=null;emit('success','Configuração excluída.');await load();}catch(error){if(current===generation)formError.value=(error as Error).message;}finally{busy.value=false;}}
void load();onBeforeUnmount(()=>{generation++;});
</script>
<template>
  <p>Configure consultas privadas usando o catálogo de sindicatos. A execução é acompanhada em Monitoramento.</p>
  <div class="registry-controls"><button v-if="canEdit" type="button" class="secondary" :disabled="loading" @click="edit()">Configurar sindicato</button><label>Buscar sindicato ou consulta<input v-model="query" type="search"></label><label>Situação<select v-model="status"><option value="todas">Todas</option><option value="true">Ativas</option><option value="false">Inativas</option></select></label><button class="secondary" type="button" :disabled="loading" @click="load">Atualizar lista</button></div>
  <p v-if="loading" role="status">Carregando sindicatos e consultas…</p><p v-else-if="failure" role="alert">{{ failure }}</p>
  <div v-else class="registry-scroll"><table><caption>Sindicatos e filtros privados</caption><thead><tr><th scope="col">Consulta e sindicato</th><th scope="col">Filtros</th><th scope="col">Instrumentos</th><th scope="col">Situação</th><th v-if="canEdit" scope="col">Ações</th></tr></thead><tbody><tr v-for="row in visible" :key="row.id"><td><strong>{{ row.nome }}</strong><small>{{ row.sindicato_nome||catalog.find(item=>item.id===row.sindicato_id)?.nome }}</small></td><td>{{ [row.cnpj_filtro,row.categoria,row.uf,row.titulo,row.vigencia].filter(Boolean).join(' · ') }}</td><td>{{ row.tipos.join(', ') }}</td><td>{{ row.ativo?'Ativa':'Inativa' }}</td><td v-if="canEdit" class="contact-row-actions"><button class="secondary" type="button" :aria-label="'Editar '+row.nome" @click="edit(row)">Editar</button><button class="secondary" type="button" :aria-label="'Excluir '+row.nome" @click="deleting=row;formError=''">Excluir</button></td></tr><tr v-if="!visible.length"><td :colspan="canEdit?5:4">{{ rows.length?'Nenhum resultado para esta busca.':'Ainda não há consultas neste escritório.' }}</td></tr></tbody></table></div>
  <AppDialog v-if="editing" :title="editedId?'Editar configuração':'Configurar sindicato'" :busy="busy" @close="editing=false"><form class="vue-form" @submit.prevent="save"><label>Sindicato do catálogo<select v-model="form.sindicato_id" required :disabled="!!editedId"><option disabled :value="0">Selecione um sindicato</option><option v-for="item in catalog" :key="item.id" :value="item.id">{{ item.nome }}</option></select></label><p v-if="!catalog.length">Nenhum sindicato disponível. Solicite o cadastro ao administrador da plataforma.</p><label>Nome da consulta<input v-model="form.nome" required minlength="2" maxlength="250"></label><label>Filtro de CNPJ<input v-model="form.cnpj_filtro" maxlength="25"></label><label>Filtro de categoria<input v-model="form.categoria" maxlength="500"></label><label>Filtro de UF<select v-model="form.uf"><option value="">Todas as UFs</option><option v-for="state in states" :key="state">{{ state }}</option></select></label><label>Palavra no título<input v-model="form.titulo" maxlength="500"></label><label>Filtro de vigência<input v-model="form.vigencia" maxlength="500"></label><fieldset class="instrument-types"><legend>Tipos de instrumento</legend><label v-for="type in types" :key="type"><input v-model="form.tipos" type="checkbox" :value="type">{{ type }}</label></fieldset><label>Situação da configuração<select v-model="form.ativo"><option :value="true">Ativa</option><option :value="false">Inativa</option></select></label><p v-if="formError" role="alert">{{ formError }}</p><footer><button class="secondary" type="button" :disabled="busy" @click="editing=false">Cancelar</button><button class="primary" type="submit" :disabled="busy||!catalog.length">{{ busy?'Salvando…':'Salvar configuração' }}</button></footer></form></AppDialog>
  <AppDialog v-if="deleting" title="Excluir configuração" :busy="busy" @close="deleting=null"><p>Excluir {{ deleting.nome }}? O sindicato do catálogo não será excluído. Configurações com histórico devem ser inativadas.</p><p v-if="formError" role="alert">{{ formError }}</p><footer><button class="secondary" type="button" autofocus :disabled="busy" @click="deleting=null">Cancelar</button><button class="danger-button" type="button" :disabled="busy" @click="remove">Excluir configuração</button></footer></AppDialog>
</template>
